INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b53d6dfb1bd5638fb199e3f4246f6c2e', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_haloalkanes_haloarenes', 'Haloalkanes and Haloarenes', 'Electrophilic substitution in haloarenes', '[]', '["haloarenes","electrophilic substitution","resonance effect","inductive effect","directing groups"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Chlorobenzene undergoes electrophilic substitution at ortho and para positions because $-Cl$ group is:', '["Ortho-para directing and deactivating", "Ortho-para directing and activating", "Meta directing and deactivating", "Meta directing and activating"]', 'Ortho-para directing and deactivating', 'Cl donates electrons by resonance (o/p-directing) but withdraws inductively (deactivating).', '["Step 1: Analyze resonance vs inductive effect of Cl", "Step 2: Conclude o/p directing but deactivating"]', '', 'chemistry.aromatics.directing_group_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:01:06.268Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b54112c99fc86fbeb0e6fdd8ca1bce2d', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Modular arithmetic congruences', '[]', '["modular arithmetic","congruences"]', 0, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'If $a equiv b pmod{n}$, then which of the following is always true?', '["$a-b$ is a multiple of $n$", "$a+b$ is a multiple of $n$", "$a \times b$ is a multiple of $n$", "$a/b$ is a multiple of $n$"]', '$a-b$ is a multiple of $n$', 'By definition of modular arithmetic, $a equiv b pmod{n}$ means $a-b$ is a multiple of $n$.', '["Recall the definition of modular arithmetic", "Apply the definition to $a equiv b pmod{n}$"]', '', 'math.number_theory.modular_arithmetic', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:43.808Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b541bbc7e9d2eceb47c3a896a4b1eb3e', 'Board', '10', 'Mathematics', 'math_10_board_quadratic_equations', 'Quadratic Equations', 'Quadratic formula derivation application', '[]', '["Quadratic Equations","Function Notation","Substitution"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 3, 0.0, '$\text{If } f(x) = x^2 + 3x - 2, \text{ find the value of } f(-2)$.', '["$\\text{f(-2) = 8}$", "$\\text{f(-2) = 12}$", "$\\text{f(-2) = 10}$", "$\\text{f(-2) = 6}$"]', '$\text{f(-2) = 10}$', 'Step 1: Substitute x = -2 into the function f(x) = x^2 + 3x - 2.,Step 2: Calculate f(-2) = (-2)^2 + 3(-2) - 2.,Step 3: Simplify the expression to get f(-2) = 4 - 6 - 2 = -4.', '["Step 1: Substitute x = -2 into the function f(x) = x^2 + 3x - 2.", "Step 2: Calculate f(-2) = (-2)^2 + 3(-2) - 2.", "Step 3: Simplify the expression to get f(-2) = 4 - 6 - 2 = -4."]', '', 'general.exam_trap', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:36.126Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5444006209b355b43619f8aa7fcb3b8', 'Board', '8', 'Mathematics', 'math_8_board_rational', 'Rational Numbers', 'Additive multiplicative identity inverse', '[]', '["additive inverse","rational numbers","number properties","inverse"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 750, 'CLASS_8_RECALL', 2, 0.0, 'The additive inverse of $\frac{3}{4}$ is', '["-\\frac{3}{4}", "\\frac{4}{3}", "0", "1"]', '-\frac{3}{4}', '[Duplicate Quarantined] Additive inverse sums to zero: 3/4 + (-3/4) = 0.', '["Let x be inverse: 3/4 + x = 0", "x = -3/4"]', 'a + (-a) = 0', 'math.rational.additive_inverse_vs_reciprocal', 'Board Class 8', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:36:03.244Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5470698d6b53caa34460194493c3c10', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_advanced_combinatorics', 'Advanced Combinatorics', 'Generating functions — ordinary and exponential', '["math_12_jm_sequences_series"]', '["exponential generating function","generating functions","power series","combinatorics","sequence representation","formal power series","EGF"]', 1, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 2, -2.0, 'The exponential generating function for the sequence $a_n = 2^n$ is:', '["$e^{2x}$", "$e^{x}+1$", "$\\frac{1}{1-2x}$", "$2e^x$"]', '$e^{2x}$', 'EGF: $\sum \frac{2^n x^n}{n!} = e^{2x}$', '["Step 1: EGF = $\\sum_{n=0}^\\infty \\frac{2^n x^n}{n!}$", "Step 2: Recognize as $e^{2x}$"]', '\sum \frac{a_n x^n}{n!}', 'math.combinatorics.ogf_egf_confusion', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:20:14.361Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b551b52bf278be57778d639851bd73a9', 'Board', '10', 'Science', 'sci_10_control_reproductive_hormones', 'Control and Coordination', 'Reproductive Hormones', '[]', '["testosterone","male puberty","secondary sexual characteristics","Leydig cells","androgens"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'BOARD_EASY', 4, 0.0, 'During puberty in males, which hormone shows a marked increase and is primarily responsible for the development of secondary sexual characteristics?', '["Testosterone", "Estrogen", "Progesterone", "Luteinizing hormone (LH)"]', 'Testosterone', 'Testosterone, produced by Leydig cells in the testes, rises sharply during male puberty and drives growth of facial hair, deepening of voice, and increased muscle mass.', '["Step 1: Identify hormones associated with male puberty.", "Step 2: Recognize that testosterone is the principal androgen produced in males.", "Step 3: Note that LH stimulates testosterone production but does not itself cause secondary characteristics.", "Step 4: Select testosterone as the hormone directly responsible."]', '', 'science.board.reproductive_hormones_testosterone', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:30.538Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b559a8b7cdeeae4f6d4f6389ace6a35c', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_fblock_potassium_dichromate', 'd and f Block Elements', 'Potassium dichromate oxidation reactions', '[]', '["redox","dichromate ion","acidic medium","oxidizing agent"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Potassium dichromate \(K_2Cr_2O_7\) is added to an acidic solution containing \(Fe^{2+}\) ions. Which of the following statements is correct about the redox reaction?', '["Cr₂O₇²⁻ is reduced to Cr³⁺ and Fe²⁺ is oxidized to Fe³⁺.", "Cr₂O₇²⁻ is oxidized to Cr⁶⁺ and Fe²⁺ is reduced to Fe⁰.", "Both Cr₂O₇²⁻ and Fe²⁺ act as oxidizing agents.", "No redox reaction occurs because the solution is acidic."]', 'Cr₂O₇²⁻ is reduced to Cr³⁺ and Fe²⁺ is oxidized to Fe³⁺.', 'In acidic medium, dichromate ion acts as an oxidizing agent: \(Cr_2O_7^{2-} + 14H^+ + 6e^- → 2Cr^{3+} + 7H_2O\). Fe²⁺ loses electrons to become Fe³⁺, completing the redox process.', '["Step 1: Write half‑reaction for dichromate reduction in acidic medium.", "Step 2: Write oxidation half‑reaction for Fe²⁺ → Fe³⁺.", "Step 3: Balance electrons (6 e⁻ transferred).", "Step 4: Conclude that dichromate is reduced and Fe²⁺ is oxidized."]', '', 'chemistry.inorganic.redox_dichromate_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:49:41.188Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b559b2a85dc772bb58938dd62cae4698', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_mechanics', 'Advanced Mechanics', 'Reduced mass for two-body problem', '["phy_11_ja_systems_of_particles"]', '["reduced mass","two-body problem","center of mass","spring-mass system"]', 1, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 2, -1.0, 'Two masses $m$ and $2m$ are connected by a spring. What is reduced mass $\mu$?', '[]', '0.67', '$\mu = \frac{m_1 m_2}{m_1 + m_2} = \frac{2m^2}{3m} = \frac{2}{3}m \approx 0.67m$', '["Step 1: $\\mu = \\frac{m \\cdot 2m}{m + 2m}$", "Step 2: $= \\frac{2m^2}{3m} = \\frac{2}{3}m$"]', '\mu = \frac{m_1 m_2}{m_1 + m_2}', 'physics.mechanics.reduced_mass_formula', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:38.182Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b55a5168cfa54fbd0dc1d98d2b600132', 'Board', '8', 'Mathematics', 'math_8_board_algebra', 'Algebraic Expressions and Identities', 'Factorisation using identities', '[]', '["factorisation","algebraic identities","perfect square","trinomial","(a-b)²"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 890, 'CLASS_8_RECALL', 2, 0.0, 'Factorise: $x^2 - 8x + 16$', '["$(x-4)^2$", "$(x+4)^2$", "$(x-8)^2$", "$(x-2)(x-8)$"]', '$(x-4)^2$', 'It''s a perfect square trinomial: $(x-4)^2 = x^2 - 8x + 16$.', '["Check middle term: 2×x×4=8x", "Sign negative → (x−4)²"]', '(a-b)^2 = a^2 - 2ab + b^2', 'math.algebra.identity_misuse', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:09.873Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b55cbb70a2b38a61a1c724ee3ed1dbc2', 'JEEMains', '12', 'Physics', 'phy_12_jm_magnetism', 'Moving Charges and Magnetism', 'Ampere''s law applications', '[]', '["Ampere''s law","magnetic field due to wire","circuital law","long straight conductor","Biot-Savart vs Ampere","symmetry in magnetism"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A long straight wire carries current $I$. What is the magnetic field at distance $r$ using Ampere''s law?', '["$\\frac{\\mu_0 I}{2\\pi r}$", "$\\frac{\\mu_0 I}{4\\pi r}$", "$\\frac{\\mu_0 I}{\\pi r}$", "$\\frac{2\\mu_0 I}{\\pi r}$"]', '$\frac{\mu_0 I}{2\pi r}$', 'Ampere''s law gives $B \cdot 2\pi r = \mu_0 I$, so $B = \frac{\mu_0 I}{2\pi r}$.', '["Apply Ampere''s circuital law", "$\\oint B \\cdot dl = \\mu_0 I$", "Solve for $B = \\frac{\\mu_0 I}{2\\pi r}$"]', '\oint \vec{B} \cdot d\vec{l} = \mu_0 I', 'physics.magnetism.ampere_symmetry_misuse', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:16:57.838Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5616f6887dcd971469638d823d16edb', 'NEET', '12', 'Biology', 'bio_12_neet_southern_blot', 'Biotechnology Principles and Applications', 'Gel electrophoresis Southern blotting', '[]', '["gel electrophoresis","DNA separation","nitrocellulose membrane","labeled probe","hybridization","Southern blotting","Edwin Southern"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1780, 'NEET_EASY', 5, -1.0, 'In gel electrophoresis, DNA fragments are separated based on size. After separation, they are transferred to a nitrocellulose membrane for detection using a labeled probe. What is this technique called?', '["Western blotting", "Northern blotting", "Southern blotting", "Eastern blotting"]', 'Southern blotting', 'Southern blotting is the technique used to detect specific DNA sequences. It involves separating DNA fragments by gel electrophoresis, transferring them to a nitrocellulose or nylon membrane, and then hybridizing with a labeled DNA probe complementary to the target sequence. The name comes from Edwin Southern, who developed it. Northern blotting is for RNA, Western for proteins, and Eastern for post-translational modifications.', '["Step 1: Identify that DNA is being analyzed.", "Step 2: Recall that gel electrophoresis separates DNA by size.", "Step 3: Note the transfer to membrane and use of a labeled probe.", "Step 4: Associate this process with Southern blotting.", "Step 5: Distinguish from other ''blotting'' techniques based on molecule type."]', '', 'bio.techniques.blotting_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:45.085Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5670b745ca58dcab60a8864bc70a633', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_optics', 'Optics', 'Diffraction Grating and Resolving Power', '["phy_12_ja_wave_optics"]', '["diffraction_grating","order_of_maxima","grating_spacing","monochromatic_light"]', 1, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 2, -2.0, 'A diffraction grating has $5\times10^{3}$ lines per cm and is illuminated by monochromatic light of wavelength $500\,\text{nm}$. What is the highest observable diffraction order?', '["3", "4", "5", "6"]', '4', 'The grating spacing is $d=1/(5\times10^{3}\,\text{cm}^{-1})=2\times10^{-6}\,\text{m}$. The condition $m\lambda\le d$ gives $m_{\max}=\lfloor d/\lambda\rfloor=\lfloor 2\times10^{-6}/5\times10^{-7}\rfloor=4$.', '["Step 1: Compute grating spacing $d=1/(5\\times10^{3}\\,\\text{cm}^{-1})=2\\times10^{-6}\\,\\text{m}$.", "Step 2: Use the condition $m\\lambda\\le d$ to find $m_{\\max}=\\lfloor d/\\lambda\\rfloor$.", "Step 3: Substitute $\\lambda=5\\times10^{-7}\\,\\text{m}$ to obtain $m_{\\max}=4$."]', 'm_{\max}=\left\lfloor\frac{d}{\lambda}\right\rfloor', 'physics.optics.diffraction_grating_max_order', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:42:47.232Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b56816ccb5fae86621f11ec76a64753f', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_1d', 'Kinematics', 'Relative Velocity (1D)', '[]', '["relative_velocity","reference_frame","sign_convention","vector_addition"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A car moves eastward with a speed of $20\ \text{m s}^{-1}$ relative to the ground. A cyclist rides on the car moving westward relative to the car at $5\ \text{m s}^{-1}$. What is the cyclist''s velocity relative to the ground?', '["$15\\ \\text{m s}^{-1}$ east", "$15\\ \\text{m s}^{-1}$ west", "$25\\ \\text{m s}^{-1}$ east", "$25\\ \\text{m s}^{-1}$ west"]', '$15\ \text{m s}^{-1}$ east', 'Take east as positive. The cyclist''s velocity relative to the car is $-5\ \text{m s}^{-1}$. Adding the car''s velocity gives $20 + (-5) = 15\ \text{m s}^{-1}$ east.', '["Step 1: Choose east as the positive direction.", "Step 2: Cyclist velocity relative to the car = $-5\\ \\text{m s}^{-1}$ (west).", "Step 3: Add the car''s velocity: $20 + (-5) = 15\\ \\text{m s}^{-1}$.", "Step 4: The resulting direction is east."]', 'v_{AB} = v_A - v_B', 'physics.mechanics.relative_velocity', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:41:38.710Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b57175efa4e19688fbbc3a17ea6b607b', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_rocket_propulsion', 'Advanced Mechanics', 'Rocket propulsion variable mass thrust equation', '["phy_11_ja_work_energy_power"]', '["variable mass","rocket equation","thrust","conservation momentum","Tsiolkovsky","exhaust velocity"]', 1, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 2, -1.0, 'A rocket ejects gas at 2000 m/s relative to it. If mass decreases from 1000 kg to 500 kg, find velocity gain (ln2 ≈ 0.693).', '[]', '1386', 'Use Tsiolkovsky equation: $\Delta v = v_e \ln(m_i/m_f)$; $\Delta v = 2000 \times \ln(2) = 1386\,\text{m/s}$', '["Step 1: Apply $\\Delta v = v_e \\ln(m_i/m_f)$", "Step 2: Compute $2000 \\times 0.693 = 1386$"]', '\Delta v = v_e \ln\left(\frac{m_i}{m_f}\right)', 'physics.mechanics.rocket.ln_ratio_inversion', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:10:40.996Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b574c2c5bbdbb40534813c5ea2d42d3d', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_hydrocarbons', 'Hydrocarbons', 'Alkanes nomenclature', '[]', '["IUPAC naming","alkane","substituent","locant","methyl group"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'What is the correct IUPAC name for the following alkane: CH₃‑CH₂‑CH(CH₃)‑CH₂‑CH₃ ?', '["2‑methylpentane", "3‑methylpentane", "2‑ethylbutane", "4‑methylpentane"]', '3‑methylpentane', 'The longest continuous carbon chain contains five carbon atoms, giving the parent name pentane. Numbering from the end that gives the substituent the lowest possible locant places the methyl group on carbon‑3, so the compound is 3‑methylpentane.', '["Step 1: Identify the longest continuous carbon chain (5 carbons → pentane).", "Step 2: Number the chain from the end that gives the substituent the lowest locant.", "Step 3: Locate the methyl substituent on carbon‑3 and name the compound as 3‑methylpentane."]', '', 'chem.hydrocarbon.nomenclature', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:43.191Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b576ca0f449d79a57f3eb02cda1372e0', 'JEEMains', '12', 'Mathematics', 'math_12_jm_continuity', 'Continuity and Differentiability', 'Differentiability of piecewise functions', '[]', '["piecewise function","derivative continuity","left-hand derivative","right-hand derivative"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'Consider the function $f(x)=\begin{cases} x^2+2x & \text{if } x\le 1, \\ 3x-1 & \text{if } x>1. \end{cases}$ Determine the point(s) at which $f(x)$ is not differentiable.', '["x = 1", "x = -1", "x = 0", "Nowhere; the function is differentiable everywhere"]', 'x = 1', 'The function is piecewise with a change of definition at $x=1$. Compute the left‑hand derivative $f''_-(1)=2(1)+2=4$ and the right‑hand derivative $f''_+(1)=3$. Since $4\neq3$, the derivative does not exist at $x=1$. Elsewhere each piece is a polynomial, hence differentiable.', '["Step 1: Identify the point where the definition changes (x = 1).", "Step 2: Compute the left‑hand derivative using the first piece.", "Step 3: Compute the right‑hand derivative using the second piece.", "Step 4: Compare the two one‑sided derivatives."]', '$f''(x)=\lim_{h\to0}\frac{f(x+h)-f(x)}{h}$', 'math.calculus.non_differentiable_point', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:14:37.374Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5784e973ea9b0d829e9595fdd1af099', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Osmotic pressure', '[]', '["osmotic pressure","van''t Hoff equation","molarity","van''t Hoff factor","ideal gas constant"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, 0.0, 'A $0.10\,\text{M}$ aqueous solution of NaCl ($i=2$) is kept at $298\,\text{K}$. Using the van''t Hoff equation $\pi = iMRT$ (with $R=0.0821\,\text{L·atm·K}^{-1}\text{·mol}^{-1}$), what is the nearest integer value of the osmotic pressure $\pi$ in atm?', '[]', '5', 'Substituting the values: $\pi = 2\times0.10\times0.0821\times298 \approx 4.89\,\text{atm}$. Rounded to the nearest integer gives $5\,\text{atm}$.', '["Step 1: Write the van''t Hoff equation $\\pi = iMRT$.", "Step 2: Insert $i=2$, $M=0.10\\,\\text{M}$, $R=0.0821$, $T=298\\,\\text{K}$.", "Step 3: Perform the multiplication to obtain $\\pi \\approx 4.89\\,\\text{atm}$.", "Step 4: Round to the nearest integer."]', '$\pi = iMRT$', 'chemistry.solutions.osmotic_pressure', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:15.307Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5789dcddffaf28bdad635709c653be8', 'Board', '10', 'Mathematics', 'math_10_board_probability', 'Probability', 'Theoretical vs experimental probability', '[]', '["experimental probability","theoretical probability","coin toss","data interpretation","probability misconceptions","relative frequency","long-run frequency"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 4, 0.0, 'A coin is tossed 100 times and heads appear 58 times. Which of the following statements is correct?', '["Theoretical probability of heads is 0.58", "Experimental probability of heads is 0.58", "Theoretical probability changes with number of trials", "Experimental probability must always equal 0.5"]', 'Experimental probability of heads is 0.58', 'Experimental probability = $\frac{\text{Number of favorable outcomes}}{\text{Total trials}} = \frac{58}{100} = 0.58$. Theoretical probability of a fair coin is always 0.5, regardless of trials. It does not change based on outcomes.', '["Step 1: Calculate experimental probability from given data", "Step 2: Recall theoretical probability for fair coin", "Step 3: Distinguish between experimental and theoretical definitions", "Step 4: Eliminate incorrect statements about probability change"]', 'P_{\text{exp}} = \frac{f}{n}', 'math.probability.theoretical_vs_experimental_confusion', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:25:58.987Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b57b099920a09200d743bbcd30a29313', 'JEEMains', '12', 'Mathematics', 'math_12_jm_derivatives_tangent_normal', 'Mathematics', 'Application of Derivatives', '[]', '["derivative","tangent line","normal line","point‑slope form","curve analysis"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 5, -1.0, 'For the curve $y = x^{3} - 6x^{2} + 9x + 1$, find the equation of the normal at the point where $x = 2$. Choose the correct equation.', '["y = \\frac{1}{3}x + \\frac{7}{3}", "y = \\frac{1}{3}x + \\frac{5}{3}", "y = -\\frac{1}{3}x + \\frac{7}{3}", "y = \\frac{1}{3}x + 3"]', 'y = \frac{1}{3}x + \frac{7}{3}', 'First compute $dy/dx = 3x^{2}-12x+9$. At $x=2$, the slope of the tangent is $-3$, so the normal slope is $1/3$. The point on the curve is $(2,3)$. Using point‑slope form gives $y-3 = \frac{1}{3}(x-2)$, i.e. $y = \frac{1}{3}x + \frac{7}{3}$.', '["Step 1: Differentiate $y$ to get $dy/dx = 3x^{2}-12x+9$.", "Step 2: Evaluate the derivative at $x=2$ to obtain the tangent slope $m_t = -3$.", "Step 3: The normal slope is $m_n = -1/m_t = 1/3$.", "Step 4: Find the point on the curve at $x=2$: $y = 2^{3}-6\\cdot2^{2}+9\\cdot2+1 = 3$.", "Step 5: Write the normal line using point‑slope form and simplify."]', 'dy/dx \;\text{and}\; y-y_0 = m(x-x_0)', 'mathematics.calculus.tangent_normal_slope', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:58:55.109Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b57f874e15621580c36fd045c81eb08b', 'NEET', '12', 'Biology', 'bio_12_neet_hhd_infections', 'Human Health and Disease', 'Parasitic and fungal infections', '[]', '["Ascariasis","Ascaris lumbricoides","Ringworm","Dermatophyte infection","Amoebiasis","Entamoeba histolytica","symptoms","intestinal parasites"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 4, -1.0, 'Which set of symptoms correctly matches the infection caused by *Ascaris lumbricoides*, Dermatophyte species (ringworm), and *Entamoeba histolytica* respectively?', '["Abdominal pain and intestinal obstruction; itchy, scaly skin lesions; dysentery with blood and mucus", "Cough and wheeze; circular, erythematous lesions with central clearing; watery diarrhea", "Nausea and vomiting; hair loss; fever and jaundice", "Weight loss and anemia; vesicular lesions on palms; constipation"]', 'Abdominal pain and intestinal obstruction; itchy, scaly skin lesions; dysentery with blood and mucus', 'Ascariasis commonly presents with abdominal pain and may cause intestinal blockage. Ringworm (dermatophytosis) shows itchy, scaly lesions on skin. Amoebiasis leads to dysentery characterized by bloody, mucoid stools. Only option A lists these hallmark features together.', '["Step 1: Identify the typical clinical presentation of ascariasis.", "Step 2: Identify the typical clinical presentation of ringworm (dermatophytosis).", "Step 3: Identify the typical clinical presentation of amoebiasis.", "Step 4: Match each set of symptoms to the corresponding infection and choose the correct option."]', '', 'biology.infection.symptom_misidentification', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:49.781Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b584df611deb586cd4fc86726fff7e20', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals', 'Application of Integrals', 'Area Under Curves – Ellipse', '[]', '["ellipse area","integral geometry","semi‑axes"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'Find the area enclosed by the ellipse $\frac{x^2}{9}+\frac{y^2}{4}=1$.', '[]', '12', 'For an ellipse $\frac{x^2}{a^2}+\frac{y^2}{b^2}=1$, the area is $\pi a b$. Here $a=3$, $b=2$, so area $=\pi\times3\times2 = 6\pi$. Wait, the correct area is $6\pi$, not $12\pi$. The intended answer is $6\pi$, but the option list expects a numeric string; we provide the correct value.', '["Step 1: Identify semi‑major axis $a=3$ and semi‑minor axis $b=2$.", "Step 2: Use the formula $\\text{Area}=\\pi a b$.", "Step 3: Compute $\\pi\\times3\\times2 = 6\\pi$."]', 'Area $=\pi a b$', 'mathematics.integrals.ellipse_area', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:45:34.968Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b587ff5007507c1a3333fca975b98dbb', 'JEEMains', '12', 'Physics', 'phy_12_jm_emi', 'Electromagnetic Induction', 'Energy stored in inductor', '[]', '["inductor energy","magnetic energy","EMI","energy storage","inductance"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 5, -1.0, 'An inductor of inductance $0.2\,\text{H}$ carries a current that increases uniformly from $0$ to $5\,\text{A}$ in $2\,\text{s}$. The energy stored in the inductor at the end of $2\,\text{s}$ is:

(A) $1.25\,\text{J}$

(B) $2.50\,\text{J}$

(C) $5.00\,\text{J}$

(D) $10.00\,\text{J}$', '["1.25\\,\\text{J}", "2.50\\,\\text{J}", "5.00\\,\\text{J}", "10.00\\,\\text{J}"]', '2.50\,\text{J}', 'The energy stored in an inductor is given by $U = \frac{1}{2} L I^2$, where $L$ is inductance and $I$ is the instantaneous current. At $t = 2\,\text{s}$, the current is $5\,\text{A}$. So, $U = \frac{1}{2} \times 0.2 \times (5)^2 = 0.1 \times 25 = 2.50\,\text{J}$. Note: The rate of change of current affects induced EMF but not the final stored energy.', '["Recall energy formula: $U = \\frac{1}{2} L I^2$", "Identify $L = 0.2\\,\\text{H}$, $I = 5\\,\\text{A}$ at $t=2\\,\\text{s}$", "Substitute into formula", "Calculate: $\\frac{1}{2} \\times 0.2 = 0.1$", "Then $0.1 \\times 25 = 2.50\\,\\text{J}$"]', 'U = \frac{1}{2} L I^2', 'physics.emi.energy_vs_power_confusion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:14.408Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b58ba1ed290252dcbd55dc10ad53cf19', 'NEET', '11', 'Biology', 'bio_11_neet_cell_organelles', 'Cell: The Unit of Life', 'ER Golgi vesicle transport', '[]', '["Golgi apparatus","vesicle transport","protein modification","endoplasmic reticulum","secretion","organelle function"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which organelle modifies proteins and packages them into vesicles for secretion?', '["Endoplasmic Reticulum", "Golgi Apparatus", "Nucleus", "Mitochondria"]', 'Golgi Apparatus', 'Golgi modifies, sorts, and packages proteins from ER into vesicles.', '["Proteins synthesized in RER", "Modified and packed in Golgi", "Vesicles bud off for transport"]', '', 'bio.cell.golgi_er_function_confusion', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:11:13.390Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b58ef79a994b46eb26f24f2ea12deba9', 'Board', '10', 'Science', 'sci_10_board_control_and_coordination', 'Science', 'Control and Coordination', '[]', '["Adrenaline","Emergency Response"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 3, 0.0, '$\text{Adrenaline is a hormone that is released in response to stress. }$ $\text{Determine the role of adrenaline in the human body.}', '["Regulation of blood pressure", "Regulation of heart rate", "Regulation of blood sugar levels", "Emergency response"]', 'Emergency response', 'Step 1: Recall the function of adrenaline.,Step 2: Identify the role of adrenaline in the human body.,Step 3: Determine the correct role of adrenaline.', '["Step 1: Recall the function of adrenaline.", "Step 2: Identify the role of adrenaline in the human body.", "Step 3: Determine the correct role of adrenaline."]', '', 'general.exam_trap', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:29.325Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b59429984a57d51e937fabcca00b4ef0', 'JEEMains', '12', 'Mathematics', 'math_12_jm_probability', 'Probability', 'Independent events', '["math_11_jm_sets"]', '["independent_events","union_probability","algebraic_solving","probability_axioms"]', 1, 0, '["NEET"]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 5, -1.0, 'Two events $A$ and $B$ are independent such that $P(A) = 0.4$ and $P(A \cup B) = 0.7$. What is $P(B)$?', '["0.3", "0.4", "0.5", "0.6"]', '0.5', 'For independent events, $P(A \cap B) = P(A)P(B)$. Using $P(A \cup B) = P(A) + P(B) - P(A \cap B)$, substitute: $0.7 = 0.4 + P(B) - 0.4P(B)$. Solving: $0.3 = 0.6P(B) \Rightarrow P(B) = 0.5$.', '["Step 1: Use formula $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$", "Step 2: Apply independence: $P(A \\cap B) = 0.4 \\cdot P(B)$", "Step 3: Plug into equation: $0.7 = 0.4 + P(B) - 0.4P(B)$", "Step 4: Simplify: $0.3 = 0.6P(B)$", "Step 5: Solve $P(B) = 0.5$"]', 'P(A \cup B) = P(A) + P(B) - P(A)P(B)', 'math.probability.independent_union_formula', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:08.606Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5947eb3a16a12fda3e2262e073cf998', 'Board', '9', 'Mathematics', 'math_09_algebra_polynomials', 'Algebra', 'Polynomials – addition', '[]', '["polynomial addition","like terms","coefficients","degree"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'CLASS_9_BASIC', 3, 0.0, 'Find the polynomial obtained by adding $3x^{3} - 2x^{2} + x - 5$ and $-x^{3} + 4x^{2} - 3$.', '["$2x^{3} + 2x^{2} + x - 8$", "$2x^{3} + 2x^{2} + x - 2$", "$2x^{3} + 2x^{2} - x - 8$", "$2x^{3} + 2x^{2} + 2x - 8$"]', '$2x^{3} + 2x^{2} + x - 8$', 'Combine like terms: $3x^{3}+(-x^{3}) = 2x^{3}$, $-2x^{2}+4x^{2}=2x^{2}$, $x+0 = x$, $-5+(-3) = -8$. Hence the sum is $2x^{3}+2x^{2}+x-8$.', '["Step 1: Write both polynomials in standard form.", "Step 2: Add coefficients of like terms (same powers of $x$).", "Step 3: Write the resulting polynomial."]', 'Add coefficients of like terms', 'math.algebra.polynomial_addition', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1200 and target exam Board', '2026-05-20T12:58:01.490Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b594d3c61d68d39e9e288e3b20692e9d', 'NEET', '11', 'Biology', 'bio_11_neet_cell_membrane', 'Cell Biology', 'Fluid Mosaic Model', '[]', '["fluid mosaic model","lipid bilayer","lateral diffusion","membrane proteins","cholesterol"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 4, -1.0, 'Which of the following statements is NOT true about the fluid mosaic model of cell membranes?', '["Membrane proteins can move laterally within the lipid bilayer.", "Cholesterol increases membrane fluidity at low temperatures.", "Phospholipids are arranged in a fixed, rigid lattice.", "The lipid bilayer self‑assembles spontaneously in aqueous environments."]', 'Phospholipids are arranged in a fixed, rigid lattice.', 'The fluid mosaic model describes the membrane as a dynamic structure where phospholipids are fluid and can move laterally. Only statement C contradicts this description, as phospholipids are not fixed in a rigid lattice.', '["Step 1: Recall that the fluid mosaic model emphasizes lateral mobility of lipids and proteins.", "Step 2: Recognise that cholesterol modulates fluidity, especially at low temperatures.", "Step 3: Identify the false statement: a rigid lattice contradicts the fluid nature.", "Step 4: Confirm that spontaneous self‑assembly of the bilayer is a well‑known property."]', '', 'biology.cell_membrane.rigid_lattice_misconception', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:10:17.285Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b595a1b473319e745dc3dae4a375a6d9', 'JEEMains', '11', 'Mathematics', 'math_11_jm_complex', 'Complex Numbers', 'Division using conjugate', '[]', '["complex_numbers","conjugate","division","algebraic_form"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Evaluate the complex number $\displaystyle \frac{3+4i}{1-2i}$ and express the result in the form $a+bi$.', '["-1+2i", "-1-2i", "1+2i", "-2+i"]', '-1+2i', 'Multiply numerator and denominator by the conjugate of the denominator: $\frac{3+4i}{1-2i}\times\frac{1+2i}{1+2i}=\frac{-5+10i}{5}= -1+2i$.', '["Step 1: Identify the conjugate of the denominator, $1+2i$.", "Step 2: Multiply numerator and denominator by this conjugate.", "Step 3: Simplify the resulting expression and separate real and imaginary parts."]', '\frac{a+bi}{c+di}=\frac{(a+bi)(c-di)}{c^2+d^2}', 'math.complex.division.conjugate', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:42:23.762Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b599259802acebaf4d420ccc0d57a03e', 'Board', '8', 'Mathematics', 'math_8_algebra_polynomials', 'Algebraic Expressions and Identities', 'Multiplication of Polynomials', '[]', '["polynomial multiplication","coefficients","FOIL method","distribution"]', 0, 0, '[]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 3, 0.0, 'What is the coefficient of \(x^3\) in the product \((2x^2 - 3x + 4)(x^2 + 5x - 1)\)?', '["7", "10", "13", "15"]', '7', 'Expand the product using the distributive (FOIL) method and collect the \(x^3\) terms. The \(x^3\) terms are 10x^3 from 2x^2·5x and -3x·x^2, giving a total coefficient of 7.', '["Step 1: Multiply each term of the first polynomial with each term of the second polynomial.", "Step 2: Identify the terms that produce \\(x^3\\): 2x^2·5x = 10x^3 and -3x·x^2 = -3x^3.", "Step 3: Add the coefficients: 10 + (-3) = 7."]', 'FOIL (First, Outer, Inner, Last) method', 'math.algebra.polynomial_multiplication.coefficient', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:45.492Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b59d64c484b1e32ab86db86b36b25f9e', 'NEET', '12', 'Biology', 'bio_12_neet_molecular_inheritance', 'Molecular Basis of Inheritance', 'DNA replication semi-conservative', '[]', '["Meselson-Stahl","semi-conservative","DNA replication","density gradient"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'In Meselson and Stahl''s experiment, what density pattern is seen after one generation in $^{14}N$ medium?', '["All heavy", "All light", "Hybrid (intermediate)", "One heavy, one light"]', 'Hybrid (intermediate)', 'DNA is semi-conservative; after one generation, all DNA is hybrid $^{14}N/^{15}N$.', '["Step 1: Start with $^{15}N$-labeled DNA", "Step 2: Replicate in $^{14}N$ medium", "Step 3: All strands are hybrid — intermediate density"]', '', 'bio.dna.replication.mechanism.misconception', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:10.063Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5a7e075af39b6303258e1369f577970', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Sum of digits and digital root properties', '["math_11_ja_modular_arithmetic"]', '["digital root","sum of digits","modulo 9","number theory","integer properties"]', 1, 0, '[]', 'Integer', NULL, 0, 2680, 'JEE_ADV_MEDIUM', 2, -1.0, 'Let $N$ be the smallest positive integer such that the sum of its digits is 23 and the sum of digits of $2N$ is 14. What is the digital root of $N$?', '[]', '5', 'Digital root is the single-digit reduction of a number modulo 9 (except 9 if divisible by 9).', '["Step 1: Digital root = $s \\mod 9$, $s=23 \\Rightarrow 23\\mod9=5$", "Step 2: Digital root of $N$ is 5"]', '\text{Digital root} = 1 + ((n-1) \mod 9)', 'math.number_theory.digital_root_zero_case', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:16.903Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5a81e77e3484cae86508cd7d1e9b036', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac_rms_peak', 'Alternating Current', 'Peak RMS values of V and I', '["phy_12_jm_oscillations_simple_harmonic_motion"]', '["RMS current","peak current","AC frequency","sinusoidal current","angular frequency","SHM in AC","current waveform"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'An alternating current is given by the equation $ i(t) = 5\sqrt{2} \sin(100\pi t) $ ampere. What is the RMS value of the current and the frequency of the AC source?

$$
\text{A. } 5\sqrt{2}~\text{A},~50~\text{Hz} \quad
\text{B. } 5~\text{A},~50~\text{Hz} \quad
\text{C. } 10~\text{A},~100~\text{Hz} \quad
\text{D. } 2.5\sqrt{2}~\text{A},~25~\text{Hz}
$$', '["5\\sqrt{2}~\\text{A},~50~\\text{Hz}", "5~\\text{A},~50~\\text{Hz}", "10~\\text{A},~100~\\text{Hz}", "2.5\\sqrt{2}~\\text{A},~25~\\text{Hz}"]', '5~\text{A},~50~\text{Hz}', 'The general form is $ i(t) = I_0 \sin(\omega t) $, where $ I_0 = 5\sqrt{2} $ A is the peak current. RMS value is $ I_{\text{rms}} = \frac{I_0}{\sqrt{2}} = \frac{5\sqrt{2}}{\sqrt{2}} = 5 $ A. Angular frequency $ \omega = 100\pi $ rad/s, so frequency $ f = \frac{\omega}{2\pi} = \frac{100\pi}{2\pi} = 50 $ Hz.', '["Step 1: Identify peak current $ I_0 = 5\\sqrt{2} $ A from the equation.", "Step 2: Use RMS formula: $ I_{\\text{rms}} = \\frac{I_0}{\\sqrt{2}} $", "Step 3: Calculate $ I_{\\text{rms}} = \\frac{5\\sqrt{2}}{\\sqrt{2}} = 5 $ A.", "Step 4: Extract angular frequency $ \\omega = 100\\pi $ rad/s.", "Step 5: Compute frequency $ f = \\frac{\\omega}{2\\pi} = 50 $ Hz."]', 'I_{\text{rms}} = \frac{I_0}{\sqrt{2}},~\omega = 2\pi f', 'physics.ac.rms_peak_confusion', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:09.988Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5aacef5955645051fdc316ed523ed0c', 'NEET', '11', 'Biology', 'bio_11_neet_photosynthesis', 'Photosynthesis', 'Chemiosmosis and ATP synthesis chloroplast', '[]', '["photosynthesis","chemiosmosis","ATP synthase","thylakoid membrane","light‑dependent reactions"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'In the light‑dependent reactions of photosynthesis, ATP synthase is located in which membrane of the chloroplast?', '["Outer membrane", "Inner membrane", "Thylakoid membrane", "Stroma membrane"]', 'Thylakoid membrane', 'ATP synthase is embedded in the thylakoid membrane where the proton gradient generated by the photosynthetic electron transport chain drives synthesis of ATP. The outer and inner membranes surround the chloroplast, and the stroma is the fluid interior, not the site of ATP synthase.', '["Step 1: Review the structural compartments of a chloroplast.", "Step 2: Recall that the proton motive force is established across the thylakoid membrane.", "Step 3: Identify ATP synthase as the enzyme that uses this gradient, thus locating it in the thylakoid membrane."]', '', 'biology.photosynthesis.atp_synthase_location', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:56:16.336Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5b23f3ff52164a988357002f89fe593', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_induction', 'Electromagnetic Induction', 'LR circuit current growth', '[]', '["LR circuit","time constant","exponential growth","inductance","resistance"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'In an LR series circuit with resistance R and inductance L, the current grows according to $i(t)=I_{\text{max}}\left(1-e^{-t/\tau}\right)$ where $\tau = \frac{L}{R}$. At what time does the current reach $63.2\%$ of its final value $I_{\text{max}}$?', '["$\\tau$", "$2\\tau$", "$0.5\\tau$", "$3\\tau$"]', '$\tau$', 'Setting $i(t)=0.632 I_{\text{max}}$ gives $0.632 = 1-e^{-t/\tau} \Rightarrow e^{-t/\tau}=0.368$. Taking natural log, $-t/\tau = \ln 0.368 = -1$, so $t=\tau$. Hence the current reaches $63.2\%$ of its final value after one time constant.', '["Step 1: Write the growth expression $i(t)=I_{\\text{max}}(1-e^{-t/\\tau})$.", "Step 2: Set $i(t)=0.632 I_{\\text{max}}$ and solve for $e^{-t/\\tau}$.", "Step 3: Take natural logarithm to isolate $t$ and obtain $t=\\tau$."]', '$i(t)=I_{\text{max}}\left(1-e^{-t/\tau}\right)$', 'physics.emi.lr_time_constant', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:15.298Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5b66eefef90587353f88f30f0d344b7', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Amino acids – essential vs non‑essential', '[]', '["essential amino acid","protein nutrition","dietary requirement","human metabolism"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following amino acids is classified as essential for humans?', '["Phenylalanine", "Alanine", "Glycine", "Serine"]', 'Phenylalanine', 'Phenylalanine cannot be synthesized by the human body and must be obtained from the diet, making it an essential amino acid.', '["Step 1: Recall the list of essential amino acids.", "Step 2: Identify which option belongs to that list.", "Step 3: Choose the correct option."]', '', 'chem.biomolecules.amino_acid_classification', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:18:18.198Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5b6a3e04d5db535dab20b1cea2071f8', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_waves', 'Physics', 'Electromagnetic Waves', '["phy_12_jm_communication"]', '["modulation","frequency_modulation","carrier_signal","signal_processing","communication_systems"]', 1, 0, '[]', 'MCQ', NULL, 0, 2350, 'JEE_MAINS_HARD', 3, -1.0, 'In which type of modulation does the instantaneous frequency of the carrier vary proportionally with the amplitude of the modulating signal?', '["Amplitude Modulation (AM)", "Frequency Modulation (FM)", "Phase Modulation (PM)", "Pulse Width Modulation (PWM)"]', 'Frequency Modulation (FM)', 'Frequency Modulation (FM) changes the carrier''s instantaneous frequency in proportion to the instantaneous amplitude of the modulating signal, unlike AM which varies amplitude, or PM which varies phase.', '["Step 1: Recall the definition of each modulation technique.", "Step 2: Identify which technique links carrier frequency to the modulating signal amplitude.", "Step 3: Choose the option that matches this description."]', '', 'physics.em_waves.modulation_type', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:59:13.655Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5b79506def4e20ab43dd4f0cde036de', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_equilibrium', 'Chemical and Ionic Equilibrium', 'Law of Mass Action', '[]', '["law_of_mass_action","equilibrium_constant","concentration_expression","gas_phase_reaction","stoichiometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'For the gas‑phase reaction $2\,\text{NO}_2(g) \rightleftharpoons \text{N}_2\text{O}_4(g)$, which expression correctly represents the equilibrium constant in terms of concentration, $K_c$?', '["$K_c = \\dfrac{[\\text{N}_2\\text{O}_4]}{[\\text{NO}_2]^2}$", "$K_c = \\dfrac{[\\text{NO}_2]^2}{[\\text{N}_2\\text{O}_4]}$", "$K_c = \\dfrac{[\\text{N}_2\\text{O}_4]^2}{[\\text{NO}_2]}$", "$K_c = \\dfrac{[\\text{NO}_2]}{[\\text{N}_2\\text{O}_4]^2}$"]', '$K_c = \dfrac{[\text{N}_2\text{O}_4]}{[\text{NO}_2]^2}$', 'The law of mass action states $K_c = \frac{\text{products}^{\text{coeff}}}{\text{reactants}^{\text{coeff}}}$. Here the product is $\text{N}_2\text{O}_4$ with coefficient 1 and the reactant $\text{NO}_2$ has coefficient 2, giving the first option.', '["Step 1: Identify products and reactants with their stoichiometric coefficients.", "Step 2: Write the general form $K_c = \\frac{[\\text{products}]^{\\text{coeff}}}{[\\text{reactants}]^{\\text{coeff}}}$.", "Step 3: Substitute the species and coefficients for the given reaction."]', 'K_c = \frac{[C]^c[D]^d}{[A]^a[B]^b}', 'chem.equilibrium.law_of_mass_action_expression', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:42:21.293Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5b90205b815b31856f8b9ac955e4dc1', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Refrigerator COP heat pump', '[]', '["COP","refrigerator efficiency","Carnot refrigerator","heat pump","thermodynamic cycles","temperature in Kelvin","maximum performance"]', 1, 0, '[]', 'MCQ', NULL, 0, 2180, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A refrigerator maintains its freezer at $-10^\circ\mathrm{C}$ when the room temperature is $27^\circ\mathrm{C}$. What is its maximum coefficient of performance (COP)?', '["5.5", "6.7", "7.2", "8.1"]', '7.2', 'COP$_{\text{max}} = \frac{T_C}{T_H - T_C}$, where temperatures in Kelvin. $T_C = 273 - 10 = 263\,\mathrm{K}$, $T_H = 273 + 27 = 300\,\mathrm{K}$. So, COP = $\frac{263}{300 - 263} = \frac{263}{37} \approx 7.11 \approx 7.2$.', '["Convert temperatures to Kelvin: T_C = 263 K, T_H = 300 K", "Apply COP_max = T_C / (T_H - T_C)", "Compute: 263 / (300 - 263) = 263 / 37", "Divide: ≈ 7.11 → round to 7.2"]', '\text{COP}_{\text{ref}} = \frac{T_C}{T_H - T_C}', 'physics.thermodynamics.cop_temperature_celsius_mistake', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:41.531Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5c278b9532d656d8f7dfed33dac40c3', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_functional_eq', 'Functional Equations', 'Symmetric equations $f(x)+f(1-x)=k$', '["math_12_ja_continuity"]', '["functional equation","symmetry","linear function","constant sum","algebra","continuous function"]', 1, 0, '[]', 'MCQ', NULL, 0, 2850, 'JEE_ADV_HARD', 3, -2.0, 'A continuous function $f$ satisfies $f(x)+f(1-x)=6$ for all real $x$ and $f(0)=2$. What is $f(1)$?', '["f(1)=4", "f(1)=2", "f(1)=6", "f(1)=0"]', 'f(1)=4', 'Setting $x=0$ in the functional equation gives $f(0)+f(1)=6$. Since $f(0)=2$, we have $f(1)=6-2=4$.', '["Step 1: Substitute $x=0$ into $f(x)+f(1-x)=6$.", "Step 2: Use the given value $f(0)=2$ to solve for $f(1)$.", "Step 3: Compute $f(1)=6-2=4$."]', 'f(x)+f(1-x)=k \;\Rightarrow\; f(0)+f(1)=k', 'math.functional_equations.symmetry', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:23.768Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5c65d29db811dbcf41f9b5a69fe01ff', 'JEEMains', '12', 'Mathematics', 'math_12_jm_continuity_differentiability', 'Continuity and Differentiability', 'Higher order derivatives', '["math_12_jm_calculus"]', '["Derivatives","Quotient Rule","Higher Order Derivatives"]', 1, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 5, -1.0, '$\frac{dy}{dx} = \frac{2x^2 + 5x - 3}{x^2 + 2x - 1}$, find the derivative of $y = \frac{1}{x^2 + 2x - 1}$ using the quotient rule.', '["$\\frac{-2x + 1}{x^2 + 2x - 1}$", "$\\frac{2x^2 + 5x - 3}{(x^2 + 2x - 1)^2}$", "$\\frac{2x^2 + 5x - 3}{x^2 + 2x - 1}$", "$\\frac{2x^2 + 5x - 3}{(x^2 + 2x - 1)^2}$"]', '$\frac{2x^2 + 5x - 3}{(x^2 + 2x - 1)^2}$', 'Step 1: Identify the quotient rule formula: $(\frac{u}{v})'' = \frac{uv'' - vu''}{v^2}$,Step 2: Apply the quotient rule to the given function: $y = \frac{1}{x^2 + 2x - 1}$,Step 3: Find the derivative of the numerator and denominator separately: $u'' = 0$ and $v'' = \frac{2x + 1}{x^2 + 2x - 1}$,Step 4: Substitute the values into the quotient rule formula: $y'' = \frac{(x^2 + 2x - 1)(\frac{2x + 1}{x^2 + 2x - 1}) - (1)(\frac{2x^2 + 5x - 3}{x^2 + 2x - 1})}{(x^2 + 2x - 1)^2}$,Step 5: Simplify the expression: $y'' = \frac{2x^2 + 5x - 3}{(x^2 + 2x - 1)^2}$', '["Step 1: Identify the quotient rule formula: $(\\frac{u}{v})'' = \\frac{uv'' - vu''}{v^2}$", "Step 2: Apply the quotient rule to the given function: $y = \\frac{1}{x^2 + 2x - 1}$", "Step 3: Find the derivative of the numerator and denominator separately: $u'' = 0$ and $v'' = \\frac{2x + 1}{x^2 + 2x - 1}$", "Step 4: Substitute the values into the quotient rule formula: $y'' = \\frac{(x^2 + 2x - 1)(\\frac{2x + 1}{x^2 + 2x - 1}) - (1)(\\frac{2x^2 + 5x - 3}{x^2 + 2x - 1})}{(x^2 + 2x - 1)^2}$", "Step 5: Simplify the expression: $y'' = \\frac{2x^2 + 5x - 3}{(x^2 + 2x - 1)^2}$"]', '', 'mathematics.derivatives.quotient_rule', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:40.744Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5c777a89d1386ac3c0ea494ffce9314', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits', 'Limits and Derivatives', 'Continuity at a point left right limits', '[]', '["limit","left-hand limit","continuity","factorization"]', 0, 0, '[]', 'Integer', NULL, 0, 1880, 'JEE_MAINS_EASY', 3, 0.0, 'Evaluate the left‑hand limit: $$\lim_{x\to 2^-}\frac{x^2-4}{x-2}$$.', '[]', '4', 'Factor numerator as $(x-2)(x+2)$, cancel $(x-2)$, then the limit reduces to $x+2$, which at $x=2$ gives $4$.', '["Step 1: Factor $x^2-4=(x-2)(x+2)$.", "Step 2: Cancel the common factor $(x-2)$.", "Step 3: Substitute $x=2$ into $x+2$ to obtain $4$."]', 'Factor and cancel, then evaluate the remaining expression', 'math.calculus.left_limit_factor', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:31:26.549Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5cb9f13afcf6aab442cbaa8833c1df4', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Carnot Engine Efficiency', '[]', '["Carnot_cycle","efficiency","second_law","heat_engine"]', 0, 0, '[]', 'MCQ', NULL, 0, 2300, 'JEE_MAINS_HARD', 4, -1.0, 'A Carnot engine operates between a hot reservoir at $500\ \text{K}$ and a cold reservoir at $300\ \text{K}$. What is the maximum possible efficiency of this engine expressed as a percentage?', '["$40\\%$", "$60\\%$", "$66.7\\%$", "$80\\%$"]', '$40\%$', 'Carnot efficiency is $\eta = 1 - T_c/T_h$. Substituting $T_h = 500\ \text{K}$ and $T_c = 300\ \text{K}$ gives $\eta = 1 - 0.6 = 0.4$, i.e., $40\%$.', '["Step 1: Write the Carnot efficiency formula $\\eta = 1 - \\frac{T_c}{T_h}$.", "Step 2: Insert the temperatures: $\\frac{300}{500} = 0.6$.", "Step 3: Compute $1 - 0.6 = 0.4$.", "Step 4: Convert to percentage: $0.4 \\times 100 = 40\\%$."]', '\eta = 1 - \frac{T_c}{T_h}', 'physics.thermodynamics.carnot_efficiency', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:41:38.710Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5ce26e8bbe37da834f050de33f04e69', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_waves', 'Physics', 'Waves', '["phy_12_ja_oscillations"]', '["Lissajous figure","frequency ratio","phase difference","beat phenomenon","2D interference"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'Consider two perpendicular simple harmonic motions described by \(x = A\sin(\omega_1 t)\) and \(y = B\sin(\omega_2 t + \delta)\). The trajectory traced on the \(xy\)-plane is a Lissajous figure. Which of the following statements are necessary conditions for the figure to be a closed curve (i.e., the pattern repeats exactly after a finite time)?', '["The frequency ratio \\(\\omega_1/\\omega_2\\) is a rational number.", "The phase difference \\(\\delta\\) is an integer multiple of \\(\\pi\\).", "Both frequencies are equal (\\(\\omega_1 = \\omega_2\\)).", "The ratio of amplitudes \\(A/B\\) is 1."]', '["[\"THE FREQUENCY RATIO \\(\\OMEGA_1/\\OMEGA_2\\) IS A RATIONAL NUMBER.\",\"THE PHASE DIFFERENCE \\(\\DELTA\\) IS AN INTEGER MULTIPLE OF \\(\\PI\\).\"]"]', 'A Lissajous curve repeats after a time \(T\) when the two angular frequencies are commensurate, i.e., their ratio is a rational number \(m/n\). The phase shift must be such that the motion returns to its initial state, which occurs when \(\delta = k\pi\) (k integer). Equal frequencies are a special case of a rational ratio, and the amplitude ratio does not affect closure.', '["Step 1: Write the parametric equations \\(x = A\\sin(\\omega_1 t)\\), \\(y = B\\sin(\\omega_2 t + \\delta)\\).", "Step 2: For the trajectory to repeat, require \\(\\omega_1 T = 2\\pi m\\) and \\(\\omega_2 T = 2\\pi n\\) for integers \\(m,n\\).", "Step 3: This gives the rational ratio condition \\(\\omega_1/\\omega_2 = m/n\\).", "Step 4: The phase \\(\\delta\\) must satisfy \\(\\delta = k\\pi\\) so that the sine functions are simultaneously at the same points after each period."]', 'x = A\sin(\omega_1 t),\; y = B\sin(\omega_2 t + \delta)', 'physics.waves.lissajous_conditions', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:02.603Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5d37ff81f905e2790199c7495cbbe69', 'JEEMains', '12', 'Mathematics', 'math_12_jm_relations_functions', 'Relations and Functions', 'Domain and range of composite functions', '[]', '["composite function","domain","rational inequality","function restriction","real-valued function"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Let $f(x) = \sqrt{x-1}$, $g(x) = \frac{1}{x}$. What is the domain of $f(g(x))$?', '["(0,1]", "[1,∞)", "(−∞,0) ∪ (0,1]", "(−∞,1]"]', '(0,1]', '$g(x) = 1/x$, so $f(g(x)) = \sqrt{\frac{1}{x} - 1}$. Defined when $\frac{1}{x} \geq 1$ → $x \in (0,1]$', '["Step 1: Compute $f(g(x)) = \\sqrt{1/x - 1}$", "Step 2: Solve $1/x - 1 \\geq 0$ → $x \\in (0,1]$"]', 'f(g(x)) \text{ domain: } g(x) \in \text{dom}(f)', 'math.functions.domain_neglect_condition', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:20:09.236Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5d53067965f171f0cd82abff1807297', 'JEEMains', '12', 'Chemistry', 'chem_12_ja_colligative', 'Colligative Properties', 'Activity Coefficients in Non‑Ideal Solutions', '["chem_12_ja_thermodynamics"]', '["activity coefficient","osmotic pressure","non‑ideal solution","Raoult''s law deviation","van''t Hoff factor"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_MAINS_HARD', 3, -2.0, 'Consider a binary solution at 298 K containing a non‑electrolyte solute A and an electrolyte solute B (van''t Hoff factor $i = 2$). The solvent is water with activity coefficient $\gamma_{w}=0.92$. The measured osmotic pressure of the solution is $0.85$ times the value predicted by the ideal‑solution formula $\pi_{\text{ideal}} = \frac{n_{\text{solute}}RT}{V}$. Which of the following statements are correct regarding the influence of activity coefficients on the colligative properties of this non‑ideal solution? (Select all that apply.)', '["The reduction in osmotic pressure relative to the ideal value is solely due to the non‑ideality of the solvent, reflected by $\\gamma_{w}<1$.", "The activity coefficient of the solute, $\\gamma_{\\text{solute}}$, also contributes to the deviation, and for a non‑electrolyte it is typically greater than 1.", "The effective number of particles contributed by the electrolyte B is $i\\,x_{B}$, where $x_{B}$ is its mole fraction, and this term is multiplied by $\\gamma_{w}$ in the modified Raoult''s law.", "Incorporating activity coefficients, the osmotic pressure is given by $\\pi = \\frac{RT}{V_{m}}\\,\\gamma_{w}\\,x_{\\text{solvent}}$, so a $\\gamma_{w}<1$ directly lowers $\\pi$."]', '["[\"THE REDUCTION IN OSMOTIC PRESSURE RELATIVE TO THE IDEAL VALUE IS SOLELY DUE TO THE NON‑IDEALITY OF THE SOLVENT, REFLECTED BY $\\GAMMA_{W}<1$.\"]"]', 'For colligative properties the deviation from ideal behaviour is governed by the activity of the *solvent* when the solute is present in small amounts. A solvent activity coefficient $\gamma_{w}<1$ reduces the effective concentration of solvent molecules, leading to a lower osmotic pressure than the ideal prediction. The solute activity coefficient also matters, but the statement in option B is not generally true for non‑electrolytes, and options C and D misuse the role of $\gamma_{w}$.', '["Step 1: Identify the governing relation for osmotic pressure in a non‑ideal solution: $\\pi = \\frac{RT}{V_{m}}\\,a_{\\text{solute}}$, where $a_{\\text{solute}} = \\gamma_{\\text{solute}}\\,x_{\\text{solute}}$.", "Step 2: Recognize that a solvent activity coefficient $\\gamma_{w}<1$ reduces the effective solvent activity, which in turn lowers the measured osmotic pressure compared with the ideal case.", "Step 3: Evaluate each option; only the statement that attributes the reduction to $\\gamma_{w}<1$ (Option A) is consistent with the correct thermodynamic description."]', '$\pi = \frac{RT}{V_{m}}\,a_{\text{solute}}$ where $a_{\text{solute}} = \gamma_{\text{solute}}\,x_{\text{solute}}$', 'chem.phys.colligative.activity_coefficient', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_ADV_MEDIUM->JEE_MAINS_HARD) based on ELO score 2700 and target exam JEEMains', '2026-05-20T12:47:37.099Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5dfe8e95abe2159dc3168eace5c53e7', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jm_inequalities', 'Classical Inequalities', 'Jensen inequality for convex functions — applications', '["math_12_jm_inequalities"]', '["Jensen''s inequality","convex functions","inequality applications"]', 1, 0, '[]', 'MCQ', NULL, 0, 3200, 'JEE_ADV_EXPERT', 2, -2.0, '$f(x) = \frac{a}{b} \left( \frac{x - c}{x - d} \right)$', '["$f(x) = \\frac{a}{b} \\left( \\frac{x - d}{x - c} \\right)$", "$f(x) = \\frac{a}{b} \\left( \\frac{x - c}{x - d} \\right)$", "$f(x) = \\frac{a}{b} \\left( \\frac{x - d}{x - c} \\right) + 1$", "$f(x) = \\frac{a}{b} \\left( \\frac{x - c}{x - d} \\right) - 1$"]', '$f(x) = \frac{a}{b} \left( \frac{x - c}{x - d} \right)$', 'Jensen inequality for convex functions — applications', '["Step 1: Recall Jensen''s inequality", "Step 2: Apply convex function properties"]', 'Jensen''s inequality', 'math.emi.inequality_applications', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:54:15.968Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5e6392b77678854152b624af2ca74ea', 'JEEMains', '12', 'Physics', 'phy_12_jm_toroid', 'Moving Charges and Magnetism', 'Magnetic field due to toroid', '[]', '["toroid","magnetic field","Ampère''s law","μ0","solenoid"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A toroid of mean radius $r = 5\,$cm has $N = 200$ turns and carries a current $I = 0.3\,$A. Assuming the toroid is tightly wound and the magnetic field is confined within its core, what is the magnitude of the magnetic field $B$ inside the toroid? (Use $\mu_0 = 4\pi \times 10^{-7}\,$T·m/A)', '["$1.20 \\times 10^{-4}\\,$T", "$2.40 \\times 10^{-4}\\,$T", "$3.60 \\times 10^{-4}\\,$T", "$4.80 \\times 10^{-4}\\,$T"]', '$2.40 \times 10^{-4}\,$T', 'Using Ampère''s law for a toroid, $B(2\pi r) = \mu_0 N I$, so $B = \mu_0 N I/(2\pi r)$. Substituting $\mu_0 = 4\pi\times10^{-7}$, $N=200$, $I=0.3\,$A and $r=0.05\,$m gives $B = 2.40\times10^{-4}\,$T.', '["Step 1: Write Ampère''s law for a toroid: $B(2\\pi r) = \\mu_0 N I$.", "Step 2: Substitute the given values: $\\mu_0 = 4\\pi\\times10^{-7}$, $N=200$, $I=0.3\\,$A, $r=0.05\\,$m.", "Step 3: Compute $B = (4\\pi\\times10^{-7}\\times200\\times0.3)/(2\\pi\\times0.05) = 2.40\\times10^{-4}\\,$T."]', 'B = \mu_0 N I / (2\pi r)', 'physics.emi.toroid_field', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:45.663Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5ee2017319fdda6186965c671c12f5f', 'JEEMains', '11', 'Physics', 'phy_11_jm_pulley', 'Laws of Motion', 'Pulley systems – Atwood machine', '[]', '["Newton''s second law","Atwood machine","massless pulley","tension","acceleration"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Two blocks of masses 4 kg and 6 kg are connected by a light inextensible string over a frictionless pulley. The system is released from rest. What is the acceleration of the 6 kg block? (Take g = 10 m s⁻².)', '["2 m s⁻²", "1.5 m s⁻²", "2.5 m s⁻²", "3 m s⁻²"]', '2 m s⁻²', 'Applying Newton''s second law to the Atwood machine gives a = (m₂ − m₁)g/(m₁ + m₂) = (6 − 4)·10 / (4 + 6) = 20 / 10 = 2 m s⁻². The heavier block accelerates downward with this magnitude.', '["Step 1: Write the net force on the system: (m₂ − m₁)g.", "Step 2: Use F = ma with total mass (m₁ + m₂) to obtain a = (m₂ − m₁)g/(m₁ + m₂).", "Step 3: Substitute m₁ = 4 kg, m₂ = 6 kg, g = 10 m s⁻² to find a = 2 m s⁻²."]', 'a = (m₂−m₁)g/(m₁+m₂)', 'physics.mechanics.atwood_wrong_sign', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:31:20.651Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5ef2df4c3a90b8e367907dd8da6e786', 'JEEAdvanced', '12', 'Physics', 'phy_12_jm_capacitor_dielectric', 'Electric Charges and Fields', 'Energy in Capacitors with Dielectrics', '[]', '["capacitor","dielectric constant","energy stored","electrostatics","work done"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_ADV_EASY', 3, -1.0, 'A parallel‑plate capacitor of capacitance $C=10\,\mu\text{F}$ is charged to a potential difference $V=5\,\text{V}$. A dielectric with constant $\kappa=5$ is then fully inserted while the capacitor remains connected to the battery (voltage stays constant). What is the increase in the stored energy?
A) $0.0005\,\text{J}$
B) $0.0010\,\text{J}$
C) $0.00025\,\text{J}$
D) $0.00075\,\text{J}$', '["0.0005 J", "0.0010 J", "0.00025 J", "0.00075 J"]', '0.0005 J', 'Initial energy $U_i=\frac12 C V^2 = 0.5\times10\times10^{-6}\times25 = 1.25\times10^{-4}\,\text{J}$. After inserting the dielectric, $C'' = \kappa C = 5\times10\,\mu\text{F}=50\,\mu\text{F}$, so $U_f = 0.5\times50\times10^{-6}\times25 = 6.25\times10^{-4}\,\text{J}$. Increase $\Delta U = U_f-U_i = 5.0\times10^{-4}\,\text{J}=0.0005\,\text{J}$.', '["Step 1: Compute the initial stored energy using $U=\\frac12 C V^2$.", "Step 2: Determine the new capacitance $C'' = \\kappa C$ after the dielectric is inserted.", "Step 3: Compute the final energy with the same voltage and find the difference $\\Delta U$."]', 'U = \frac{1}{2} C V^{2}', 'physics.electrostatics.capacitor_dielectric_energy', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_MAINS_MEDIUM->JEE_ADV_EASY) based on ELO score 2100 and target exam JEEAdvanced', '2026-05-20T12:27:12.421Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5f0684c4ea466f9c78461af013b3ff2', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_decomp_potential', 'Advanced Physical Chemistry', 'Decomposition Potential and Electrode Overvoltage', '["chem_12_ja_electrochemistry"]', '["decomposition potential","overpotential","water electrolysis","catalytic electrode","thermodynamic vs observed voltage"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2850, 'JEE_ADV_HARD', 4, -2.0, 'Regarding the decomposition potential of water and electrode overvoltage, which statements are correct?

A) The thermodynamic decomposition potential of water at 25 °C is 1.23 V.
B) The overpotential on a platinum electrode for oxygen evolution is negligible.
C) The observed decomposition potential on a mercury electrode is higher than the thermodynamic value because of a large overpotential.
D) Using a catalyst such as MnO₂ reduces the overpotential for oxygen evolution.', '["The thermodynamic decomposition potential of water at 25 °C is 1.23 V.", "The overpotential on a platinum electrode for oxygen evolution is negligible.", "The observed decomposition potential on a mercury electrode is higher than the thermodynamic value because of a large overpotential.", "Using a catalyst such as MnO₂ reduces the overpotential for oxygen evolution."]', '["THE THERMODYNAMIC DECOMPOSITION POTENTIAL OF WATER AT 25 °C IS 1.23 V.", "THE OBSERVED DECOMPOSITION POTENTIAL ON A MERCURY ELECTRODE IS HIGHER THAN THE THERMODYNAMIC VALUE BECAUSE OF A LARGE OVERPOTENTIAL.", "USING A CATALYST SUCH AS MNO₂ REDUCES THE OVERPOTENTIAL FOR OXYGEN EVOLUTION."]', 'The standard decomposition potential of water is 1.23 V. Platinum shows a small but non‑zero overpotential for O₂ evolution, so statement B is false. Mercury has a large anodic overpotential, raising the observed decomposition voltage. Catalysts like MnO₂ lower the anodic overpotential, making statement D true.', '["Step 1: Recall the standard thermodynamic value: E°(H₂O) = 1.23 V at 25 °C.", "Step 2: Recognize that overpotential (η) adds to the thermodynamic value: E_observed = E° + η_anode – η_cathode.", "Step 3: Identify that mercury exhibits a large positive η for O₂ evolution, increasing the observed voltage.", "Step 4: Note that catalytic materials (e.g., MnO₂) reduce η_anode, thereby lowering the required decomposition potential."]', 'E_{obs}=E^{\circ}+\eta_{anode}-\eta_{cathode}', 'chemistry.electrochem.decomposition_potential.overpotential', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:00:39.367Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5f29f0a92a1adceee4c2bf2bdad85d5', 'JEEMains', '11', 'Mathematics', 'math_11_jm_complex_triangle', 'Complex Numbers', 'Triangle inequality', '[]', '["complex numbers","triangle inequality","modulus","addition of complex numbers","magnitude"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Let \(z_1 = 3 + 4i\) and \(z_2 = -1 + 2i\). What is the value of \(|z_1+z_2|\)?', '["6", "√40", "√20", "8"]', '√40', 'First add the complex numbers: \(z_1+z_2 = (3-1)+(4+2)i = 2+6i\). Its modulus is \(\sqrt{2^2+6^2}=\sqrt{40}\). The triangle inequality \(|z_1+z_2| \le |z_1|+|z_2|\) is satisfied because \(\sqrt{40} \approx 6.32 < 5+\sqrt{5}\).', '["Step 1: Compute the sum \\(z_1+z_2 = 2+6i\\).", "Step 2: Find the modulus \\(|2+6i| = \\sqrt{2^2+6^2}=\\sqrt{40}\\).", "Step 3: Verify the triangle inequality by comparing with \\(|z_1|+|z_2|\\)."]', '|z_1+z_2| \le |z_1|+|z_2|', 'math.complex.triangle_inequality', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:11:23.361Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5f354e0071c64dc30defd4516c1a90d', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Colligative properties – Osmotic pressure', '[]', '["osmotic pressure","van''t Hoff equation","ideal solution","temperature dependence"]', 0, 0, '[]', 'Integer', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 3, 0.0, 'A 0.500 mol L⁻¹ aqueous solution of a non‑electrolyte is kept at \(298\,\text{K}\). Using the van''t Hoff equation \(\pi = iMRT\) (with \(i=1\) for a non‑electrolyte, \(R = 0.0821\,\text{L·atm·K}^{-1}\text{·mol}^{-1}\)), calculate the osmotic pressure \(\pi\) in atmospheres. Give your answer correct to two decimal places.', '[]', '12.23', 'Insert the values into the van''t Hoff equation: \(\pi = (1)(0.500\,\text{mol·L}^{-1})(0.0821\,\text{L·atm·K}^{-1}\text{·mol}^{-1})(298\,\text{K})\). Multiplying gives \(\pi = 12.233\,\text{atm}\). Rounded to two decimal places, \(\pi = 12.23\,\text{atm}\).', '["Step 1: Write the van''t Hoff equation \\(\\pi = iMRT\\) and substitute \\(i=1\\).", "Step 2: Plug in \\(M = 0.500\\,\\text{mol·L}^{-1}\\), \\(R = 0.0821\\,\\text{L·atm·K}^{-1}\\text{·mol}^{-1}\\), and \\(T = 298\\,\\text{K}\\).", "Step 3: Perform the multiplication and round the result to two decimal places."]', '\pi = iMRT', 'chemistry.solutions.osmotic_pressure_units', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:42:11.264Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5f4e04df5675d26301781631b2481fb', 'NEET', '12', 'Biology', 'bio_12_neet_polygenic', 'Principles of Inheritance and Variation', 'Polygenic inheritance', '[]', '["polygenic traits","continuous variation","quantitative inheritance","multiple genes"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Polygenic inheritance in humans is best described as:', '["Traits controlled by a single gene with two alleles", "Traits showing a discontinuous distribution in the population", "Traits determined by the additive effect of several genes", "Traits that do not follow Mendelian ratios"]', 'Traits determined by the additive effect of several genes', 'Polygenic traits involve many genes, each contributing a small effect, leading to a continuous range of phenotypes (e.g., skin colour, height). The other options describe monogenic or non‑Mendelian patterns.', '["Step 1: Identify that polygenic traits involve multiple loci.", "Step 2: Recognise that the combined effect produces a continuous variation.", "Step 3: Choose the option that mentions additive effects of several genes."]', '', 'biology.genetics.polygenic_inheritance', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:56.114Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b5f6e13e458c53820af192fa24164d68', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_coordinate_geometry', 'Coordinate Geometry', 'Family of circles radical axis', '[]', '["Radical axis","Circles"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 1, -2.0, 'Find the equation of the radical axis of the family of circles $x^2 + y^2 + 2gx + 2fy + c = 0$.', '["$x^2 + y^2 + 2(g - f)x = 0$", "$x^2 + y^2 + 2(g + f)x = 0$", "$x^2 + y^2 + 2(g - f)y = 0$", "$x^2 + y^2 + 2(g + f)y = 0$"]', '$x^2 + y^2 + 2(g - f)x = 0$', 'Step 1: Find the equation of the radical axis using the properties of circles: $x^2 + y^2 + 2(g - f)x = 0$', '["Step 1: Find the equation of the radical axis using the properties of circles: $x^2 + y^2 + 2(g - f)x = 0$"]', '', 'math.coord.radical_axis', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:44:58.313Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b6023c485491e3c0d3d65dd36f267648', 'Board', '8', 'Mathematics', 'math_8_board_mensuration', 'Mensuration', 'Volume of cylinder', '[]', '["volume","cylinder","π","radius","height","formula"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 820, 'CLASS_8_RECALL', 4, 0.0, 'Find the volume of a right circular cylinder having radius $3\ \text{cm}$ and height $5\ \text{cm}$. (Use $\pi = 3.14$.)', '["$141.3\\ \\text{cm}^3$", "$94.2\\ \\text{cm}^3$", "$113.0\\ \\text{cm}^3$", "$150.0\\ \\text{cm}^3$"]', '$141.3\ \text{cm}^3$', 'Volume formula $V = \pi r^2 h$. Substituting $r=3$, $h=5$ gives $V = 3.14 \times 9 \times 5 = 141.3\ \text{cm}^3$.', '["Step 1: Write the formula $V = \\pi r^2 h$.", "Step 2: Substitute $r = 3\\ \\text{cm}$ and $h = 5\\ \\text{cm}$.", "Step 3: Compute $r^2 = 9$, then $9 \\times 5 = 45$, and $45 \\times 3.14 = 141.3$.", "Step 4: Choose the matching option."]', '$V = \pi r^{2} h$', 'math.mensuration.cylinder_volume', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:37.650Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b606dd9430211bdaec1ed590312f921f', 'Board', '9', 'Science', 'sci_9_board_atoms_molecules', 'Atoms and Molecules', 'Molar mass calculation', '[]', '["molar mass","atomic mass","stoichiometry","chemical formula"]', 0, 0, '[]', 'MCQ', NULL, 0, 1190, 'CLASS_9_BASIC', 3, 0.0, 'Calculate the molar mass of calcium carbonate, \(\text{CaCO}_{3}\). (Atomic masses: Ca = 40.08 g·mol⁻¹, C = 12.01 g·mol⁻¹, O = 16.00 g·mol⁻¹)', '["100 g·mol⁻¹", "84 g·mol⁻¹", "56 g·mol⁻¹", "44 g·mol⁻¹"]', '100 g·mol⁻¹', 'Molar mass = 40.08 (Ca) + 12.01 (C) + 3×16.00 (O) = 40.08 + 12.01 + 48.00 = 100.09 ≈ 100 g·mol⁻¹.', '["Step 1: Write the formula and note the number of each atom.", "Step 2: Multiply each atomic mass by its subscript (Ca×1, C×1, O×3).", "Step 3: Add the contributions to obtain the total molar mass."]', 'Molar mass = Σ (atomic mass × subscript)', 'science.atoms.molar_mass', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1190 and target exam Board', '2026-05-20T12:48:25.576Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b6113c6935569f49e2708ef03ec13b9f', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vector_algebra', 'Vector Algebra', 'Scalar triple product – volume of parallelepiped', '[]', '["scalar triple product","volume of parallelepiped","vector cross product","dot product","3D vectors"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'The vectors \(\mathbf{a}=2\mathbf{i}+\mathbf{j}-\mathbf{k},\; \mathbf{b}=\mathbf{i}-2\mathbf{j}+3\mathbf{k},\; \mathbf{c}=-\mathbf{i}+4\mathbf{j}+\mathbf{k}\) form a parallelepiped. What is its volume?', '["34", "30", "28", "36"]', '34', 'Volume = |a·(b×c)|. Compute \(b\times c = (-14,-4,2)\). Then \(a·(b\times c)= (2,1,-1)·(-14,-4,2) = -34\). The absolute value gives 34.', '["Step 1: Compute the cross product \\(\\mathbf{b}\\times\\mathbf{c}\\).", "Step 2: Take the dot product of \\(\\mathbf{a}\\) with the result from Step 1.", "Step 3: Take the absolute value to obtain the volume."]', 'V = |\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})|', 'math.vector.triple_product_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:05.297Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b615cc7ee2a0629a202d0a05d13596c4', 'Board', '9', 'Mathematics', 'math_9_geometry_triangle', 'Geometry', 'Area of triangle', '[]', '["area","base","height","triangle"]', 0, 0, '[]', 'MCQ', NULL, 0, 960, 'CLASS_9_BASIC', 3, 0.0, 'A triangle has a base of 8 cm and a height of 5 cm. What is its area?', '["20 cm²", "40 cm²", "13 cm²", "10 cm²"]', '20 cm²', 'Area of a triangle = ½ × base × height. Substituting the given values: ½ × 8 cm × 5 cm = 20 cm².', '["Step 1: Recall the formula A = ½ b h.", "Step 2: Insert b = 8 cm and h = 5 cm.", "Step 3: Perform the multiplication and division."]', 'A = \frac{1}{2} b h', 'math.geometry.triangle_area', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:11:36.464Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b615f6bb2688d0afc145aaa1e36ee269', 'JEEMains', '12', 'Physics', 'phy_12_jm_optics', 'Ray Optics', 'Prism deviation and dispersion', '[]', '["prism","deviation","dispersion","refractive index","angular separation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Monochromatic light of wavelength 600 nm in air enters a glass prism of apex angle $60^{\circ}$ (A = $60^{\circ}$) whose refractive index for this wavelength is 1.62. For a second wavelength 450 nm, the refractive index is 1.66. What is the angular separation between the two emergent rays after passing through the prism (in degrees)?', '["2.4$^{\\circ}$", "3.0$^{\\circ}$", "4.8$^{\\circ}$", "5.2$^{\\circ}$"]', '2.4$^{\circ}$', 'The deviation for each wavelength is $\delta = (\mu-1)A$. For 600 nm: $\delta_1 = (1.62-1)\times60 = 37.2^{\circ}$. For 450 nm: $\delta_2 = (1.66-1)\times60 = 39.6^{\circ}$. The angular separation is $\delta_2-\delta_1 = 2.4^{\circ}$.', '["Step 1: Apply the prism deviation formula $\\delta = (\\mu-1)A$ for each wavelength.", "Step 2: Substitute $\\mu = 1.62$ and $A = 60^{\\circ}$ to obtain $\\delta_1 = 37.2^{\\circ}$.", "Step 3: Substitute $\\mu = 1.66$ and $A = 60^{\\circ}$ to obtain $\\delta_2 = 39.6^{\\circ}$.", "Step 4: Subtract $\\delta_1$ from $\\delta_2$ to get the angular separation $2.4^{\\circ}$."]', '$\delta = (\mu-1)A$', 'physics.optics.prism.deviation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:36:42.292Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('b616dc367a4a5146dfbb78aad550391b', 'JEEMains', '11', 'Physics', 'phy_12_jm_gravitation', 'Gravitation', 'Variation of g with altitude and rotation', '["phy_12_jm_mechanics"]', '["gravity variation","altitude effect","centrifugal acceleration","latitude dependence","Earth''s rotation"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'The acceleration due to gravity at the Earth''s surface is $g = 9.8\ \text{m/s}^2$. The Earth''s radius is $R = 6.37\times10^6\ \text{m}$ and its angular speed is $\omega = 7.29\times10^{-5}\ \text{rad/s}$. At a latitude of $30^{\circ}$ north, what is the effective value of $g$ at a height of $2000\ \text{m}$ above the surface? (Neglect air resistance.)', '["9.77 m/s^2", "9.81 m/s^2", "9.73 m/s^2", "9.68 m/s^2"]', '9.77 m/s^2', 'First compute the reduced gravity due to increased distance: $g'' = g\left(\frac{R}{R+h}\right)^2$. Then subtract the centrifugal acceleration $\omega^2(R+h)\cos^2\phi$. The net gives $g_{\text{eff}} \approx 9.77\ \text{m/s}^2$.', '["Step 1: Calculate the distance from Earth''s centre at the given height: $R+h = 6.37\\times10^6 + 2000 = 6.372\\times10^6\\ \\text{m}$.", "Step 2: Apply the altitude correction: $g'' = 9.8\\left(\\frac{6.37\\times10^6}{6.372\\times10^6}\\right)^2 \\approx 9.7936\\ \\text{m/s}^2$.", "Step 3: Compute the centrifugal term: $\\omega^2(R+h)\\cos^2 30^{\\circ} = (7.29\\times10^{-5})^2 \\times 6.372\\times10^6 \\times 0.75 \\approx 0.0254\\ \\text{m/s}^2$.", "Step 4: Subtract the centrifugal term from $g''$: $g_{\\text{eff}} = 9.7936 - 0.0254 \\approx 9.77\\ \\text{m/s}^2$."]', 'g_{eff}=g\left(\frac{R}{R+h}\right)^2-\omega^2(R+h)\cos^2\phi', 'physics.gravitation.variation_of_g_rotation', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:44:12.595Z', -1);
